public enum PhonePastEnding {
    public static func words(_ ending: PhoneJSON) -> String {
        let label = ending["label"].text ?? PhoneMessages.`pastEndingAnOption`()
        return switch (ending["how"].text ?? "unknown", ending["by"].text ?? "captain") {
        case ("chose", "firstmate"): PhoneMessages.`pastEndingFirstmateChose`(label: label)
        case ("chose", "crewmate"): PhoneMessages.`pastEndingCrewmateChose`(label: label)
        case ("chose", _): PhoneMessages.`pastEndingYouChose`(label: label)
        case ("dismissed", _): PhoneMessages.`pastEndingDismissed`()
        case ("author-withdrawal", _): PhoneMessages.`pastEndingAuthorWithdrawal`()
        case ("host-withdrawal", _): PhoneMessages.`pastEndingHostWithdrawal`()
        case ("task-retired", _): PhoneMessages.`pastEndingTaskRetired`()
        case ("duplicate", _): PhoneMessages.`pastEndingDuplicate`()
        case ("unknown", _): PhoneMessages.`pastEndingUnknown`()
        default: PhoneMessages.`pastEndingUnknown`()
        }
    }
}

